bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker logs "$cid" 2>&1 | grep -Fq 'CREATOR_DM_POLL_READY=PASS' || exit 62
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try{
 const r=await pool.query(`SELECT j.status,count(*)::int AS n FROM videobot_owner_update_jobs j JOIN videobot_listings l ON l.seller_user_id=j.owner_id WHERE l.listing_id=$1 GROUP BY j.status`,['v26nov24invoice']);
 console.log('OWNER_JOB_COUNTS',JSON.stringify(r.rows));
 const q=await pool.query(`SELECT count(*)::int AS n FROM videobot_owner_update_jobs j JOIN videobot_listings l ON l.seller_user_id=j.owner_id WHERE l.listing_id=$1 AND j.status='queued' AND EXISTS (SELECT 1 FROM videobot_owner_update_jobs e WHERE e.owner_id=j.owner_id AND e.update_id<j.update_id AND e.status='needs_reconcile')`,['v26nov24invoice']);
 console.log('BLOCKED_OWNER_QUEUE',q.rows[0].n);
 const m=await pool.query(`SELECT count(*)::int AS n FROM videobot_owner_update_jobs j JOIN videobot_listings l ON l.seller_user_id=j.owner_id WHERE l.listing_id=$1 AND j.status='queued' AND ((j.payload->'callback_query'->>'data') LIKE 'menu:%' OR (j.payload->'message'->>'text') ~ '^/start($| )')`,['v26nov24invoice']);
 console.log('QUEUED_MENU',m.rows[0].n);
 const s=await pool.query(`SELECT s.state->>'publishing' AS publishing,s.state->>'screen' AS screen FROM videobot_creator_sessions s JOIN videobot_listings l ON l.seller_user_id=s.owner_user_id WHERE l.listing_id=$1`,['v26nov24invoice']);
 console.log('SESSION',JSON.stringify(s.rows));
 const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
 const base=process.env.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org';
 try{const result=await fetch(base+'/bot'+token+'/getWebhookInfo',{signal:AbortSignal.timeout(10000)}).then(r=>r.json());console.log('BOT_API',JSON.stringify({ok:result.ok,webhook:!!result.result?.url,pending:result.result?.pending_update_count}));}catch(e){console.log('BOT_API_PROBE_FAILED',e.name)}
 if(q.rows[0].n>0&&m.rows[0].n>0)process.exitCode=73;
 else if(q.rows[0].n>0)process.exitCode=74;
}finally{await pool.end()}
JS
